#!/usr/bin/env python3
"""
Interactive Demo: Finite Probe Representability

Explores finite categories, probe families, and presheaves,
demonstrating the core theorems:
1. Probe separation → injective measurement map
2. Finite values + finite category → finite representable cover
3. Measurement cardinality bounds

Run: python demo.py
"""

# === Inlined from algorithms.py ===
"""
Algorithms for Finite Probe Representability.

Implements the core algorithms from the research paper:
1. Probe separation verification
2. Probe restriction (measurement) map computation
3. Finite representable cover construction
4. Greedy minimal cover optimization

All algorithms operate on finite categories represented as:
- objects: list of hashable identifiers
- morphisms: dict mapping (source, target) to list of morphism identifiers
- composition: dict mapping (f, g) to f∘g (where g : A→B, f : B→C gives f∘g : A→C)
- identity: dict mapping object to its identity morphism

Presheaves are represented as:
- values: dict mapping object to a finite set of elements
- restriction: dict mapping morphism to a function (dict) from target values to source values
"""

from typing import Any, Callable
from itertools import product as cartesian_product


class FiniteCategory:
    """A finite category with explicit objects, morphisms, and composition."""

    def __init__(
        self,
        objects: list,
        hom: dict[tuple, list],
        compose: dict[tuple, Any],
        identity: dict,
    ):
        """
        Args:
            objects: List of objects.
            hom: Maps (source, target) to list of morphisms.
            compose: Maps (f, g) to f∘g where g:A→B, f:B→C.
            identity: Maps object to its identity morphism.
        """
        self.objects = objects
        self.hom = hom
        self.compose = compose
        self.identity = identity

    def morphisms_from(self, source: Any, target: Any) -> list:
        """All morphisms from source to target."""
        return self.hom.get((source, target), [])

    def all_morphisms(self) -> list[tuple]:
        """All (source, target, morphism) triples."""
        result = []
        for (s, t), morphs in self.hom.items():
            for m in morphs:
                result.append((s, t, m))
        return result

    @staticmethod
    def discrete(n: int) -> "FiniteCategory":
        """Discrete category on n objects (only identity morphisms)."""
        objects = list(range(n))
        hom = {(i, i): [f"id_{i}"] for i in objects}
        compose = {(f"id_{i}", f"id_{i}"): f"id_{i}" for i in objects}
        identity = {i: f"id_{i}" for i in objects}
        return FiniteCategory(objects, hom, compose, identity)

    @staticmethod
    def linear(n: int) -> "FiniteCategory":
        """Linear order category 0 → 1 → ... → n-1 with all composites."""
        objects = list(range(n))
        hom: dict[tuple, list] = {}
        compose: dict[tuple, Any] = {}
        identity = {}

        # Create morphisms f_{i,j} : i → j for i ≤ j
        for i in objects:
            for j in objects:
                if i <= j:
                    name = f"f_{i}_{j}"
                    hom.setdefault((i, j), []).append(name)

        # Identities
        for i in objects:
            identity[i] = f"f_{i}_{i}"

        # Composition: f_{j,k} ∘ f_{i,j} = f_{i,k}
        for i in objects:
            for j in objects:
                for k in objects:
                    if i <= j <= k:
                        compose[(f"f_{j}_{k}", f"f_{i}_{j}")] = f"f_{i}_{k}"

        return FiniteCategory(objects, hom, compose, identity)

    @staticmethod
    def complete(n: int) -> "FiniteCategory":
        """Complete category on n objects: one morphism between each pair plus identities."""
        objects = list(range(n))
        hom: dict[tuple, list] = {}
        compose: dict[tuple, Any] = {}
        identity = {}

        for i in objects:
            for j in objects:
                name = f"f_{i}_{j}"
                hom.setdefault((i, j), []).append(name)

        for i in objects:
            identity[i] = f"f_{i}_{i}"

        # Composition: f_{j,k} ∘ f_{i,j} = f_{i,k}
        for i in objects:
            for j in objects:
                for k in objects:
                    compose[(f"f_{j}_{k}", f"f_{i}_{j}")] = f"f_{i}_{k}"

        return FiniteCategory(objects, hom, compose, identity)


class Presheaf:
    """A presheaf F : C^op → Set on a finite category."""

    def __init__(
        self,
        cat: FiniteCategory,
        values: dict[Any, list],
        action: dict[Any, dict],
    ):
        """
        Args:
            cat: The underlying category.
            values: Maps object Y to list of elements of F(op Y).
            action: Maps morphism f:Z→Y to dict from F(op Y) elements to F(op Z) elements.
                    This is the presheaf action F.map(f.op).
        """
        self.cat = cat
        self.values = values
        self.action = action

    def restrict(self, morphism: Any, element: Any) -> Any:
        """Apply F.map(f.op) to an element. morphism f : Z → Y, element ∈ F(op Y)."""
        return self.action[morphism][element]


def verify_probe_separation(
    cat: FiniteCategory, probe_family: list, presheaf: Presheaf
) -> tuple[bool, str]:
    """
    Verify that a probe family separates elements of a presheaf.

    Algorithm: For each object Y and each distinct pair (x, y) in F(op Y),
    check if there exists Z ∈ P and f : Z → Y such that F.map(f.op)(x) ≠ F.map(f.op)(y).

    Returns:
        (True, message) if separation holds.
        (False, counterexample_description) if separation fails.
    """
    for Y in cat.objects:
        elements = presheaf.values[Y]
        for i, x in enumerate(elements):
            for j, y in enumerate(elements):
                if i >= j:
                    continue
                separated = False
                for Z in probe_family:
                    for f in cat.morphisms_from(Z, Y):
                        if presheaf.restrict(f, x) != presheaf.restrict(f, y):
                            separated = True
                            break
                    if separated:
                        break
                if not separated:
                    return (
                        False,
                        f"Elements {x} and {y} at object {Y} are not separated by probes",
                    )
    return (True, "All elements separated")


def compute_probe_restriction_map(
    cat: FiniteCategory, probe_family: list, presheaf: Presheaf, Y: Any
) -> dict:
    """
    Compute the probe restriction map Φ_{P,F,Y} for each element of F(op Y).

    Returns dict mapping element → measurement signature.
    The measurement signature is a tuple of tuples recording all restrictions.
    """
    result = {}
    for x in presheaf.values[Y]:
        signature = []
        for Z in sorted(probe_family):
            for f in cat.morphisms_from(Z, Y):
                signature.append((Z, f, presheaf.restrict(f, x)))
        result[x] = tuple(signature)
    return result


def finite_representable_cover(
    cat: FiniteCategory, presheaf: Presheaf
) -> list[tuple]:
    """
    Construct a finite representable cover (naive algorithm).

    For each object Y and each element z ∈ F(op Y), create generator (Y, z).
    The generator (Y, z) covers element z' at object Y' via morphism f : Y' → Y
    whenever F.map(f.op)(z) = z'.

    Returns list of (object, element) pairs.
    """
    generators = []
    for Y in cat.objects:
        for z in presheaf.values[Y]:
            generators.append((Y, z))
    return generators


def compute_coverage(
    cat: FiniteCategory, presheaf: Presheaf, generator: tuple
) -> set[tuple]:
    """
    Compute all elements covered by a generator (X, x).

    Element (Y, z) is covered if there exists f : Y → X with F.map(f.op)(x) = z.
    """
    X, x = generator
    covered = set()
    for Y in cat.objects:
        for f in cat.morphisms_from(Y, X):
            z = presheaf.restrict(f, x)
            covered.add((Y, z))
    return covered


def greedy_minimal_cover(
    cat: FiniteCategory, presheaf: Presheaf
) -> list[tuple]:
    """
    Compute a greedy approximation to the minimal representable cover.

    At each step, select the generator covering the most uncovered elements.

    Returns list of (object, element) generators.
    """
    all_generators = finite_representable_cover(cat, presheaf)

    # Precompute coverage for each generator
    coverage = {g: compute_coverage(cat, presheaf, g) for g in all_generators}

    uncovered = set()
    for Y in cat.objects:
        for z in presheaf.values[Y]:
            uncovered.add((Y, z))

    selected = []
    while uncovered:
        # Find generator covering most uncovered elements
        best_gen = max(all_generators, key=lambda g: len(coverage[g] & uncovered))
        selected.append(best_gen)
        uncovered -= coverage[best_gen]

    return selected


def verify_cover(
    cat: FiniteCategory, presheaf: Presheaf, generators: list[tuple]
) -> tuple[bool, str]:
    """
    Verify that a set of generators forms a valid representable cover.

    For each (Y, z) in the presheaf, check that some generator (X, x) covers it.

    Returns:
        (True, message) if cover is valid.
        (False, counterexample) if some element is not covered.
    """
    for Y in cat.objects:
        for z in presheaf.values[Y]:
            covered = False
            for X, x in generators:
                for f in cat.morphisms_from(Y, X):
                    if presheaf.restrict(f, x) == z:
                        covered = True
                        break
                if covered:
                    break
            if not covered:
                return (False, f"Element {z} at object {Y} not covered")
    return (True, "All elements covered")



# === End inlined code ===


def print_header(title: str):
    print(f"\n{'=' * 60}")
    print(f"  {title}")
    print(f"{'=' * 60}")


def print_section(title: str):
    print(f"\n--- {title} ---")


def demo_discrete_category():
    """Demo 1: Discrete category — no non-identity morphisms."""
    print_header("DEMO 1: Discrete Category on 3 Objects")
    cat = FiniteCategory.discrete(3)

    print(f"Objects: {cat.objects}")
    print(f"Morphisms: only identities")

    # Presheaf: F(0)={a,b}, F(1)={c}, F(2)={d,e,f}
    values = {0: ["a", "b"], 1: ["c"], 2: ["d", "e", "f"]}
    action = {
        "id_0": {"a": "a", "b": "b"},
        "id_1": {"c": "c"},
        "id_2": {"d": "d", "e": "e", "f": "f"},
    }
    F = Presheaf(cat, values, action)

    total_elements = sum(len(v) for v in values.values())
    print(f"\nPresheaf: F(0)={values[0]}, F(1)={values[1]}, F(2)={values[2]}")
    print(f"Total elements: {total_elements}")

    # Probe separation
    print_section("Probe Separation")
    for probe in [[0], [1], [0, 1, 2]]:
        sep, msg = verify_probe_separation(cat, probe, F)
        print(f"  P = {probe}: {'✓' if sep else '✗'} {msg}")

    # In discrete category, only P = all objects separates
    # because identity is the only morphism

    # Measurement map
    print_section("Measurement Map (P = all objects)")
    for Y in cat.objects:
        mmap = compute_probe_restriction_map(cat, cat.objects, F, Y)
        print(f"  Object {Y}:")
        for elem, sig in mmap.items():
            print(f"    {elem} → {sig}")

    # Representable cover
    print_section("Representable Cover")
    cover = finite_representable_cover(cat, F)
    min_cover = greedy_minimal_cover(cat, F)
    print(f"  Naive generators: {len(cover)}")
    print(f"  Greedy generators: {len(min_cover)}")
    print(f"  (In discrete category, no reduction possible: {len(cover)} = {len(min_cover)})")


def demo_linear_category():
    """Demo 2: Linear order category — demonstrates cover reduction."""
    print_header("DEMO 2: Linear Category (0 → 1 → 2)")
    cat = FiniteCategory.linear(3)

    print(f"Objects: {cat.objects}")
    print("Morphisms: f_i_j : i → j for i ≤ j")
    for (s, t), ms in sorted(cat.hom.items()):
        print(f"  Hom({s},{t}) = {ms}")

    # Presheaf: chain of injections
    # F(2)={x}, F(1)={a,b}, F(0)={p,q,r}
    # F(f_1_2)(x) = a, F(f_0_1)(a)=p, F(f_0_1)(b)=q
    # F(f_0_2)(x) = p
    values = {0: ["p", "q", "r"], 1: ["a", "b"], 2: ["x"]}
    action = {
        "f_0_0": {"p": "p", "q": "q", "r": "r"},
        "f_1_1": {"a": "a", "b": "b"},
        "f_2_2": {"x": "x"},
        "f_0_1": {"a": "p", "b": "q"},
        "f_1_2": {"x": "a"},
        "f_0_2": {"x": "p"},
    }
    F = Presheaf(cat, values, action)

    total = sum(len(v) for v in values.values())
    print(f"\nPresheaf: F(0)={values[0]}, F(1)={values[1]}, F(2)={values[2]}")
    print(f"Total elements: {total}")

    # Probe separation tests
    print_section("Probe Separation Tests")
    for probe in [[0], [1], [2], [0, 1], [0, 1, 2]]:
        sep, msg = verify_probe_separation(cat, probe, F)
        status = "✓" if sep else "✗"
        print(f"  P = {probe}: {status} — {msg}")

    # Measurement maps
    print_section("Measurement Map (P = {0})")
    for Y in cat.objects:
        mmap = compute_probe_restriction_map(cat, [0], F, Y)
        print(f"  Object {Y}:")
        for elem, sig in mmap.items():
            sig_short = [(z, f, v) for z, f, v in sig]
            print(f"    {elem} → {sig_short}")

    # Information-theoretic bound
    print_section("Information-Theoretic Bound (Theorem 2)")
    probe = [0]
    for Y in cat.objects:
        fiber_size = len(values[Y])
        # Measurement space size = product over Z in P of |F(Z)|^|Hom(Z,Y)|
        meas_size = 1
        for Z in probe:
            hom_size = len(cat.morphisms_from(Z, Y))
            fz_size = len(values[Z])
            meas_size *= fz_size ** hom_size
        print(f"  Object {Y}: |F({Y})| = {fiber_size} ≤ {meas_size} = |MeasurementSpace|")

    # Cover construction and optimization
    print_section("Representable Cover Construction (Theorem 4)")
    cover = finite_representable_cover(cat, F)
    print(f"  Naive generators ({len(cover)}):")
    for g in cover:
        cov = compute_coverage(cat, F, g)
        print(f"    {g} covers: {sorted(cov)}")

    print_section("Greedy Optimized Cover")
    min_cover = greedy_minimal_cover(cat, F)
    print(f"  Greedy generators ({len(min_cover)}):")
    for g in min_cover:
        cov = compute_coverage(cat, F, g)
        print(f"    {g} covers: {sorted(cov)}")

    valid, msg = verify_cover(cat, F, min_cover)
    print(f"  Cover valid: {valid}")
    print(f"  Compression: {len(cover)} → {len(min_cover)} generators "
          f"({100 * (1 - len(min_cover) / len(cover)):.0f}% reduction)")


def demo_complete_category():
    """Demo 3: Complete category on 2 objects — maximal morphism structure."""
    print_header("DEMO 3: Complete Category on 2 Objects")
    cat = FiniteCategory.complete(2)

    print(f"Objects: {cat.objects}")
    for (s, t), ms in sorted(cat.hom.items()):
        print(f"  Hom({s},{t}) = {ms}")

    # Presheaf: F(0)={a,b,c}, F(1)={x,y}
    # F(f_0_1)(x)=a, F(f_0_1)(y)=b (restriction from 1 to 0)
    # F(f_1_0)(a)=x, F(f_1_0)(b)=x, F(f_1_0)(c)=y
    values = {0: ["a", "b", "c"], 1: ["x", "y"]}
    action = {
        "f_0_0": {"a": "a", "b": "b", "c": "c"},
        "f_1_1": {"x": "x", "y": "y"},
        "f_0_1": {"x": "a", "y": "b"},
        "f_1_0": {"a": "x", "b": "x", "c": "y"},
    }
    F = Presheaf(cat, values, action)

    print(f"\nPresheaf: F(0)={values[0]}, F(1)={values[1]}")

    print_section("Probe Separation")
    for probe in [[0], [1], [0, 1]]:
        sep, msg = verify_probe_separation(cat, probe, F)
        print(f"  P = {probe}: {'✓' if sep else '✗'} — {msg}")

    print_section("Representable Cover")
    cover = finite_representable_cover(cat, F)
    min_cover = greedy_minimal_cover(cat, F)
    print(f"  Naive: {len(cover)} generators")
    print(f"  Greedy: {len(min_cover)} generators")
    for g in min_cover:
        cov = compute_coverage(cat, F, g)
        print(f"    {g} covers: {sorted(cov)}")
    valid, msg = verify_cover(cat, F, min_cover)
    print(f"  Valid: {valid}")


def demo_counterexample_search():
    """Demo 4: Search for presheaves where probe separation fails."""
    print_header("DEMO 4: Counterexample Search — When Probes Fail")

    cat = FiniteCategory.linear(3)

    # Presheaf where probe {2} does NOT separate elements at object 0
    # because there are no morphisms from 2 to 0
    values = {0: ["a", "b"], 1: ["c"], 2: ["x"]}
    action = {
        "f_0_0": {"a": "a", "b": "b"},
        "f_1_1": {"c": "c"},
        "f_2_2": {"x": "x"},
        "f_0_1": {"c": "a"},
        "f_1_2": {"x": "c"},
        "f_0_2": {"x": "a"},
    }
    F = Presheaf(cat, values, action)

    print("Linear category 0 → 1 → 2")
    print(f"Presheaf: F(0)={values[0]}, F(1)={values[1]}, F(2)={values[2]}")

    print_section("Probe {2} — Terminal object as sole probe")
    sep, msg = verify_probe_separation(cat, [2], F)
    print(f"  Separated: {'✓' if sep else '✗'} — {msg}")
    print("  Explanation: No morphisms from 2 to 0, so elements a,b at 0 are invisible.")

    print_section("Probe {0} — Initial object as sole probe")
    sep, msg = verify_probe_separation(cat, [0], F)
    print(f"  Separated: {'✓' if sep else '✗'} — {msg}")
    print("  Explanation: 0 maps to all objects, so all elements are visible from 0.")

    print("\n  KEY INSIGHT: In directed categories, probes must be 'upstream'")
    print("  (have outgoing morphisms to all objects) to separate elements.")
    print("  This mirrors compressed sensing: measurements must 'reach' all components.")


def demo_measurement_bounds():
    """Demo 5: Information-theoretic bounds in action."""
    print_header("DEMO 5: Information-Theoretic Bounds")

    cat = FiniteCategory.linear(4)
    print("Linear category 0 → 1 → 2 → 3")

    # Presheaf with decreasing fiber sizes (injective restrictions)
    values = {
        0: [f"a{i}" for i in range(8)],
        1: [f"b{i}" for i in range(4)],
        2: [f"c{i}" for i in range(2)],
        3: ["d0"],
    }
    # Build consistent restriction maps
    action = {}
    for i in range(4):
        action[f"f_{i}_{i}"] = {v: v for v in values[i]}

    # f_0_1: b_i → a_{2i}
    action["f_0_1"] = {f"b{i}": f"a{2 * i}" for i in range(4)}
    # f_1_2: c_i → b_{2i}
    action["f_1_2"] = {f"c{i}": f"b{2 * i}" for i in range(2)}
    # f_2_3: d0 → c0
    action["f_2_3"] = {"d0": "c0"}
    # Composites
    action["f_0_2"] = {f"c{i}": f"a{4 * i}" for i in range(2)}
    action["f_1_3"] = {"d0": "b0"}
    action["f_0_3"] = {"d0": "a0"}

    F = Presheaf(cat, values, action)

    print(f"\nFiber sizes: {[len(values[i]) for i in range(4)]}")

    print_section("Cardinality Bounds with Different Probe Families")
    for probe in [[0], [3], [0, 3], [0, 1, 2, 3]]:
        print(f"\n  Probe family P = {probe}:")
        for Y in range(4):
            fiber_size = len(values[Y])
            meas_size = 1
            for Z in probe:
                hom_size = len(cat.morphisms_from(Z, Y))
                if hom_size > 0:
                    fz_size = len(values[Z])
                    meas_size *= fz_size ** hom_size
            bound_tight = "TIGHT" if fiber_size == meas_size else f"slack by {meas_size - fiber_size}"
            print(f"    |F({Y})| = {fiber_size:3d} ≤ {meas_size:6d} = |MeasSpace|  [{bound_tight}]")


def demo_summary():
    """Summary statistics across all demo categories."""
    print_header("SUMMARY: Representable Cover Statistics")

    categories = {
        "Discrete(3)": FiniteCategory.discrete(3),
        "Linear(3)": FiniteCategory.linear(3),
        "Complete(2)": FiniteCategory.complete(2),
        "Linear(4)": FiniteCategory.linear(4),
    }

    presheaves = {}

    # Discrete(3)
    presheaves["Discrete(3)"] = Presheaf(
        categories["Discrete(3)"],
        {0: ["a", "b"], 1: ["c"], 2: ["d", "e", "f"]},
        {"id_0": {"a": "a", "b": "b"}, "id_1": {"c": "c"},
         "id_2": {"d": "d", "e": "e", "f": "f"}},
    )

    # Linear(3)
    presheaves["Linear(3)"] = Presheaf(
        categories["Linear(3)"],
        {0: ["p", "q", "r"], 1: ["a", "b"], 2: ["x"]},
        {"f_0_0": {"p": "p", "q": "q", "r": "r"},
         "f_1_1": {"a": "a", "b": "b"}, "f_2_2": {"x": "x"},
         "f_0_1": {"a": "p", "b": "q"}, "f_1_2": {"x": "a"},
         "f_0_2": {"x": "p"}},
    )

    # Complete(2)
    presheaves["Complete(2)"] = Presheaf(
        categories["Complete(2)"],
        {0: ["a", "b", "c"], 1: ["x", "y"]},
        {"f_0_0": {"a": "a", "b": "b", "c": "c"},
         "f_1_1": {"x": "x", "y": "y"},
         "f_0_1": {"x": "a", "y": "b"},
         "f_1_0": {"a": "x", "b": "x", "c": "y"}},
    )

    # Linear(4)
    presheaves["Linear(4)"] = Presheaf(
        categories["Linear(4)"],
        {0: ["a0", "a1", "a2", "a3"], 1: ["b0", "b1"], 2: ["c0"], 3: ["d0"]},
        {"f_0_0": {f"a{i}": f"a{i}" for i in range(4)},
         "f_1_1": {"b0": "b0", "b1": "b1"}, "f_2_2": {"c0": "c0"},
         "f_3_3": {"d0": "d0"},
         "f_0_1": {"b0": "a0", "b1": "a1"},
         "f_1_2": {"c0": "b0"}, "f_0_2": {"c0": "a0"},
         "f_2_3": {"d0": "c0"}, "f_1_3": {"d0": "b0"},
         "f_0_3": {"d0": "a0"}},
    )

    print(f"\n{'Category':<14} {'Objects':>7} {'Morphisms':>9} {'Elements':>8} "
          f"{'Naive':>5} {'Greedy':>6} {'Reduction':>9}")
    print("-" * 64)

    for name in categories:
        cat = categories[name]
        F = presheaves[name]
        n_obj = len(cat.objects)
        n_mor = sum(len(ms) for ms in cat.hom.values())
        n_elem = sum(len(v) for v in F.values.values())
        naive = len(finite_representable_cover(cat, F))
        greedy = len(greedy_minimal_cover(cat, F))
        reduction = f"{100 * (1 - greedy / naive):.0f}%"
        print(f"{name:<14} {n_obj:>7} {n_mor:>9} {n_elem:>8} "
              f"{naive:>5} {greedy:>6} {reduction:>9}")


if __name__ == "__main__":
    demo_discrete_category()
    demo_linear_category()
    demo_complete_category()
    demo_counterexample_search()
    demo_measurement_bounds()
    demo_summary()

